arguments.command:
python3 -c "
import parse

# Test valid patterns (should work)
try:
    p = parse.Parser('{name}')
    print('OK: {name} parsed')
except ValueError as e:
    print(f'ERROR: {e}')

try:
    p = parse.Parser('{{hello}}')
    print('OK: {{hello}} parsed')
except ValueError as e:
    print(f'ERROR: {e}')

try:
    p = parse.Parser('Hello {name}')
    print('OK: Hello {name} parsed')
except ValueError as e:
    print(f'ERROR: {e}')

# Test invalid patterns (should raise ValueError)
for pattern in ['{hello', 'hello}', '{a{b}}', 'a{b']:
    try:
        p = parse.Parser(pattern)
        print(f'ERROR: {pattern!r} should have raised ValueError')
    except ValueError as e:
        print(f'OK: {pattern!r} raised ValueError: {e}')
"
